#!/usr/bin/env python3
"""Verify the self-signed TLS certificate at /app/ssl/server.crt."""
import datetime
import subprocess
import sys

CERT_PATH = "/app/ssl/server.crt"


def openssl_field(*args):
    out = subprocess.check_output(["openssl", "x509", "-in", CERT_PATH, "-noout", *args])
    return out.decode().strip()


def parse_openssl_date(value):
    """Parse an OpenSSL 'notAfter' style date into a date object."""
    value = value.split("=", 1)[-1].strip()
    for fmt in ("%b %d %H:%M:%S %Y %Z", "%b %d %H:%M:%S %Y"):
        try:
            return datetime.datetime.strptime(value, fmt)
        except ValueError:
            continue
    raise ValueError(f"Cannot parse date: {value}")


def load_common_name(subject):
    for part in subject.replace("subject=", "").split(","):
        part = part.strip()
        if part.upper().startswith("CN"):
            return part.split("=", 1)[1].strip()
    # Fallback for slash-delimited subjects
    for part in subject.split("/"):
        if part.strip().upper().startswith("CN="):
            return part.split("=", 1)[1].strip()
    return ""


def main():
    import os

    if not os.path.exists(CERT_PATH):
        print(f"ERROR: certificate not found at {CERT_PATH}")
        sys.exit(1)

    try:
        subject = openssl_field("-subject")
        not_after = openssl_field("-enddate")
    except subprocess.CalledProcessError as exc:
        print(f"ERROR: unable to load certificate: {exc}")
        sys.exit(1)

    common_name = load_common_name(subject)
    expiration = parse_openssl_date(not_after)

    print(f"Certificate: {CERT_PATH}")
    print(f"Common Name: {common_name}")
    print(f"Expiration Date: {expiration.strftime('%Y-%m-%d')}")
    print("Certificate verification successful")


if __name__ == "__main__":
    main()
